package com.cowave.search.utils

import com.cowave.search.config.DictionaryConfig
import com.cowave.search.domain.dictionary.Type
import org.springframework.stereotype.Component
import java.io.File

/**
 * 사전 바이너리 컴파일러
 * ES 인덱스에서 읽은 사전 데이터를 바이너리 파일로 컴파일
 *
 * 기존 Java analysis-product의 사전 바이너리 형식과 100% 호환
 */
@Component
class DictionaryBinaryCompile(
    private val dictionaryConfig: DictionaryConfig,
) {
    /**
     * 설정된 출력 경로 반환
     */
    fun getOutputPath(): String = dictionaryConfig.outputPath

    /**
     * Type에 따른 출력 파일 경로 반환 (설정된 경로 사용)
     */
    fun getOutputFile(type: Type): File = File(dictionaryConfig.outputPath, getOutputFileName(type))

    /**
     * ES에서 조회한 Dictionary 목록을 설정된 경로에 컴파일
     * @param dictionaries ES에서 조회한 사전 데이터 (keyword, value 쌍)
     * @param type 사전 타입
     * @param ignoreCase 대소문자 무시 여부
     * @return 생성된 파일
     */
    fun compileToConfiguredPath(
        dictionaries: List<Pair<String?, String?>>,
        type: Type,
        ignoreCase: Boolean = true,
    ): File {
        val outputFile = getOutputFile(type)
        compileFromDictionaries(dictionaries, type, outputFile, ignoreCase)
        return outputFile
    }

    /**
     * 설정된 경로에서 사전 파일 로드
     * @param type 사전 타입
     * @param ignoreCase 대소문자 무시 여부
     * @return 로드된 사전 데이터
     */
    fun loadFromConfiguredPath(
        type: Type,
        ignoreCase: Boolean = true,
    ): Any = load(type, getOutputFile(type), ignoreCase)

    /**
     * 기존 Type enum과 매핑하여 사전 컴파일
     * SET 타입: STOP, UNIT, USER, ENGLISH
     * SYNONYM 타입: SYNONYM, UNIT_SYNONYM
     * SPACE 타입: SPACE
     * COMPOUND 타입: COMPOUND
     */
    fun compile(
        type: Type,
        data: Any,
        outputFile: File,
    ) {
        outputFile.parentFile?.mkdirs()

        when (type) {
            Type.STOP, Type.UNIT, Type.USER, Type.ENGLISH -> {
                SetDictionarySerializer.writeTo(data as SetDictionaryData, outputFile)
            }

            Type.SYNONYM, Type.UNIT_SYNONYM -> {
                SynonymDictionarySerializer.writeTo(data as SynonymDictionaryData, outputFile)
            }

            Type.SPACE -> {
                SpaceDictionarySerializer.writeTo(data as SpaceDictionaryData, outputFile)

